-- DDL de referencia gerado do modelo EF Core; nao e uma migration nem um dump de producao.
-- Nao contem dados de usuarios ou seeds. Consulte as migrations para atualizar uma instalacao.

CREATE TABLE "Courses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nome" text NOT NULL,
    "Description" text NOT NULL,
    "Preco" numeric NOT NULL,
    "Image" text NOT NULL,
    "Category" text NOT NULL,
    "DeliveryMode" text NOT NULL DEFAULT 'presencial',
    "WorkloadHours" integer NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Courses" PRIMARY KEY ("Id")
);

CREATE TABLE "PromoCodes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Discount" numeric NOT NULL,
    "DiscountType" text NOT NULL,
    "StartDate" text NOT NULL,
    "EndDate" text NOT NULL,
    "IsActive" boolean NOT NULL,
    "UsageLimit" integer,
    "UsageCount" integer NOT NULL,
    CONSTRAINT "PK_PromoCodes" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nome" text NOT NULL,
    "Email" text NOT NULL,
    "Cpf" text NOT NULL,
    "Phone" text NOT NULL,
    "Street" text NOT NULL,
    "Number" text NOT NULL,
    "Complement" text NOT NULL,
    "Neighborhood" text NOT NULL,
    "City" text NOT NULL,
    "State" text NOT NULL,
    "ZipCode" text NOT NULL,
    "SenhaHash" text NOT NULL,
    "Role" text NOT NULL,
    "FailedLoginAttempts" integer NOT NULL,
    "LockoutEnd" timestamp with time zone,
    CONSTRAINT "PK_Users" PRIMARY KEY ("ID")
);

CREATE TABLE "CourseAssessments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CourseId" integer NOT NULL,
    "Title" text NOT NULL,
    "MinimumScore" integer NOT NULL,
    "MaxAttempts" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_CourseAssessments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseAssessments_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE CASCADE
);

CREATE TABLE "CourseClasses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CourseId" integer NOT NULL,
    "DataRealizacao" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone,
    "Local" text NOT NULL,
    "Instructor" text NOT NULL,
    "Capacity" integer NOT NULL DEFAULT 0,
    "AvailableSeats" integer NOT NULL DEFAULT 0,
    "Status" text NOT NULL DEFAULT 'scheduled',
    CONSTRAINT "PK_CourseClasses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseClasses_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CourseInterests" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CourseId" integer NOT NULL,
    "Name" text NOT NULL,
    "Email" text NOT NULL,
    "Phone" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "Status" text NOT NULL,
    CONSTRAINT "PK_CourseInterests" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseInterests_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE CASCADE
);

CREATE TABLE "CourseModules" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CourseId" integer NOT NULL,
    "Title" text NOT NULL,
    "SortOrder" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_CourseModules" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseModules_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AuditLogs" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer,
    "Action" text NOT NULL,
    "EntityType" text NOT NULL,
    "EntityId" text NOT NULL,
    "PreviousValue" text,
    "NewValue" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AuditLogs_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("ID") ON DELETE SET NULL
);

CREATE TABLE "CourseCertificates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "CourseId" integer NOT NULL,
    "ValidationCode" text NOT NULL,
    "IssuedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_CourseCertificates" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseCertificates_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CourseCertificates_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("ID") ON DELETE CASCADE
);

CREATE TABLE "CourseProgresses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "CourseId" integer NOT NULL,
    "Percent" double precision NOT NULL,
    "CompletedLessons" text NOT NULL,
    "LastSeenAt" timestamp with time zone,
    "CompletedAt" timestamp with time zone,
    CONSTRAINT "PK_CourseProgresses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseProgresses_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("ID") ON DELETE CASCADE
);

CREATE TABLE "Orders" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" integer NOT NULL,
    "DataPedido" timestamp with time zone NOT NULL,
    "Status" text NOT NULL DEFAULT 'pending',
    "PaymentStatus" text NOT NULL DEFAULT 'pending',
    "Total" numeric NOT NULL,
    "ValorFrete" numeric NOT NULL,
    "PaymentMethod" text NOT NULL,
    "Installments" integer,
    "PromoCodeId" integer,
    "PromoCode" text NOT NULL,
    "GatewayPaymentId" text,
    "PaidAt" timestamp with time zone,
    "IdempotencyKey" text,
    CONSTRAINT "PK_Orders" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Orders_PromoCodes_PromoCodeId" FOREIGN KEY ("PromoCodeId") REFERENCES "PromoCodes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Orders_Users_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Users" ("ID") ON DELETE CASCADE
);

CREATE TABLE "RefreshTokens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Token" text NOT NULL,
    "UserId" integer NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "RevokedAt" timestamp with time zone,
    "ReplacedByToken" text,
    CONSTRAINT "PK_RefreshTokens" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RefreshTokens_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("ID") ON DELETE CASCADE
);

CREATE TABLE "Students" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer,
    "Name" text NOT NULL,
    "Email" text NOT NULL,
    "Phone" text NOT NULL,
    "CourseId" text NOT NULL,
    "CourseName" text NOT NULL,
    "EnrollmentDate" text NOT NULL,
    "Status" text NOT NULL,
    CONSTRAINT "PK_Students" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Students_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("ID") ON DELETE SET NULL
);

CREATE TABLE "CourseAssessmentAttempts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "CourseId" integer NOT NULL,
    "AssessmentId" integer NOT NULL,
    "AttemptNumber" integer NOT NULL,
    "Score" integer NOT NULL,
    "Passed" boolean NOT NULL,
    "SubmittedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_CourseAssessmentAttempts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseAssessmentAttempts_CourseAssessments_AssessmentId" FOREIGN KEY ("AssessmentId") REFERENCES "CourseAssessments" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CourseAssessmentAttempts_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CourseAssessmentAttempts_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("ID") ON DELETE CASCADE
);

CREATE TABLE "CourseQuestions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AssessmentId" integer NOT NULL,
    "Statement" text NOT NULL,
    "SortOrder" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_CourseQuestions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseQuestions_CourseAssessments_AssessmentId" FOREIGN KEY ("AssessmentId") REFERENCES "CourseAssessments" ("Id") ON DELETE CASCADE
);

CREATE TABLE "CourseLessons" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ModuleId" integer NOT NULL,
    "Title" text NOT NULL,
    "Description" text NOT NULL,
    "VideoUrl" text NOT NULL,
    "DurationMinutes" integer NOT NULL,
    "SortOrder" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_CourseLessons" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseLessons_CourseModules_ModuleId" FOREIGN KEY ("ModuleId") REFERENCES "CourseModules" ("Id") ON DELETE CASCADE
);

CREATE TABLE "OrderItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PedidoId" integer NOT NULL,
    "CourseId" integer,
    "NameSnapshot" text NOT NULL,
    "ItemType" text NOT NULL,
    "TurmaId" integer,
    "Quantidade" integer NOT NULL,
    "PrecoUnitario" numeric NOT NULL,
    CONSTRAINT "PK_OrderItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrderItems_CourseClasses_TurmaId" FOREIGN KEY ("TurmaId") REFERENCES "CourseClasses" ("Id"),
    CONSTRAINT "FK_OrderItems_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_OrderItems_Orders_PedidoId" FOREIGN KEY ("PedidoId") REFERENCES "Orders" ("Id") ON DELETE CASCADE
);

CREATE TABLE "PaymentWebhookEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EventId" text NOT NULL,
    "OrderId" integer NOT NULL,
    "PaymentId" text NOT NULL,
    "Status" text NOT NULL,
    "ReceivedAt" timestamp with time zone NOT NULL,
    "ProcessedAt" timestamp with time zone,
    CONSTRAINT "PK_PaymentWebhookEvents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PaymentWebhookEvents_Orders_OrderId" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Enrollments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ClassId" integer,
    "CourseId" integer,
    "StudentId" integer NOT NULL,
    "OrderId" integer NOT NULL,
    "Status" text NOT NULL,
    "ParticipationConfirmedAt" timestamp with time zone,
    "ParticipationStartDate" timestamp with time zone,
    "EnrolledAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Enrollments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Enrollments_CourseClasses_ClassId" FOREIGN KEY ("ClassId") REFERENCES "CourseClasses" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Enrollments_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Enrollments_Orders_OrderId" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Enrollments_Students_StudentId" FOREIGN KEY ("StudentId") REFERENCES "Students" ("Id") ON DELETE CASCADE
);

CREATE TABLE "CourseQuestionOptions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "QuestionId" integer NOT NULL,
    "Text" text NOT NULL,
    "IsCorrect" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    CONSTRAINT "PK_CourseQuestionOptions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseQuestionOptions_CourseQuestions_QuestionId" FOREIGN KEY ("QuestionId") REFERENCES "CourseQuestions" ("Id") ON DELETE CASCADE
);

CREATE TABLE "CourseAssessmentAnswers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AttemptId" integer NOT NULL,
    "QuestionId" integer NOT NULL,
    "SelectedOptionId" integer NOT NULL,
    "IsCorrect" boolean NOT NULL,
    CONSTRAINT "PK_CourseAssessmentAnswers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CourseAssessmentAnswers_CourseAssessmentAttempts_AttemptId" FOREIGN KEY ("AttemptId") REFERENCES "CourseAssessmentAttempts" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CourseAssessmentAnswers_CourseQuestionOptions_SelectedOptio~" FOREIGN KEY ("SelectedOptionId") REFERENCES "CourseQuestionOptions" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CourseAssessmentAnswers_CourseQuestions_QuestionId" FOREIGN KEY ("QuestionId") REFERENCES "CourseQuestions" ("Id") ON DELETE CASCADE
);

